import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Atlas region fallback
  const rect = (config.atlasRegion && config.atlasRegion.sourceRect) || {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
  };

  const aspect = rect.width / rect.height;
  const geometry = new PlaneGeometry(aspect, 1);

  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  // Load texture asynchronously
  let _texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      _texture = tex;

      // Simple UV mapping (full texture). If atlas offsets are needed, compute them here.
      const uvNode = uv(); // default UVs
      material.mapNode = texture(tex, uvNode);
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);

  // Billboard: always face the camera
  mesh.onBeforeRender = function (_, __, camera) {
    mesh.quaternion.copy(camera.quaternion);
  };

  const root = new Group();
  root.add(mesh);

  // No interaction handlers for this node
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (_texture) _texture.dispose();
    // No GSAP timelines were created for this node
  };

  return root;
}
